from pathlib import Path
import sys
root = Path(sys.argv[1])

def replace(path, old, new):
    p = root / path
    s = p.read_text()
    if old not in s:
        raise SystemExit(f'expected block missing: {path}')
    p.write_text(s.replace(old, new, 1))

